import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface FileData {
  file: File;
  previewUrl: string;
  base64: string;
  mimeType: string;
}

export interface AnalysisResult {
  text: string;
  timestamp: string;
}

export enum AppState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { MODEL_NAME, SYSTEM_INSTRUCTION } from "../constants";

// Initialize Gemini Client
// API Key is guaranteed to be in process.env.API_KEY per system instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeContent = async (
  base64Data: string,
  mimeType: string,
  promptText: string
): Promise<string> => {
  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Data,
              mimeType: mimeType,
            },
          },
          {
            text: promptText || "Analyze this content and provide a detailed reconnaissance report.",
          },
        ],
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    return response.text || "No analysis generated.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

import React, { useRef, useState } from 'react';
import { Upload, FileImage, X } from 'lucide-react';
import { ACCEPTED_IMAGE_TYPES } from '../constants';
import { FileData } from '../types';

interface FileUploaderProps {
  onFileSelect: (fileData: FileData) => void;
  selectedFile: FileData | null;
  onClear: () => void;
  disabled: boolean;
}

export const FileUploader: React.FC<FileUploaderProps> = ({ onFileSelect, selectedFile, onClear, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = (file: File) => {
    if (!file) return;

    // Check type roughly (server/api handles strict checks, this is UX)
    if (!file.type.startsWith('image/')) {
        alert("System currently optimized for Image Reconnaissance.");
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target?.result as string;
      // Extract base64 part
      const base64 = result.split(',')[1];
      onFileSelect({
        file,
        previewUrl: result,
        base64,
        mimeType: file.type
      });
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  return (
    <div className="w-full">
      {!selectedFile ? (
        <div
          onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={handleDrop}
          onClick={() => !disabled && fileInputRef.current?.click()}
          className={`
            relative group cursor-pointer 
            border-2 border-dashed rounded-lg p-12 
            transition-all duration-300 ease-in-out
            flex flex-col items-center justify-center
            ${isDragging 
              ? 'border-recon-accent bg-recon-accent-dim' 
              : 'border-recon-gray hover:border-recon-muted bg-recon-dark/50 hover:bg-recon-gray/20'}
            ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
          `}
        >
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleChange}
            accept={ACCEPTED_IMAGE_TYPES}
            className="hidden"
            disabled={disabled}
          />

          <div className={`p-4 rounded-full bg-recon-gray mb-4 group-hover:scale-110 transition-transform ${isDragging ? 'text-recon-accent' : 'text-gray-400'}`}>
            <Upload className="w-8 h-8" />
          </div>

          <h3 className="text-lg font-mono font-medium text-gray-300 mb-1">
            Drop Intelligence Here
          </h3>
          <p className="text-xs text-gray-500 font-mono">
            SUPPORTED: PNG, JPG, WEBP
          </p>

          {/* Decorative corners */}
          <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-recon-gray group-hover:border-recon-accent transition-colors"></div>
          <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-recon-gray group-hover:border-recon-accent transition-colors"></div>
          <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-recon-gray group-hover:border-recon-accent transition-colors"></div>
          <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-recon-gray group-hover:border-recon-accent transition-colors"></div>
        </div>
      ) : (
        <div className="relative rounded-lg overflow-hidden border border-recon-gray bg-recon-dark group">
          <img 
            src={selectedFile.previewUrl} 
            alt="Preview" 
            className="w-full h-64 md:h-96 object-contain bg-black/50"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-4">
             <div className="flex justify-between items-end">
                <div className="font-mono text-xs text-recon-accent">
                    <p>FILE: {selectedFile.file.name}</p>
                    <p>SIZE: {(selectedFile.file.size / 1024).toFixed(2)} KB</p>
                </div>
                <button 
                    onClick={(e) => { e.stopPropagation(); onClear(); }}
                    disabled={disabled}
                    className="p-2 bg-red-500/20 hover:bg-red-500/40 text-red-500 rounded-full border border-red-500/50 transition-colors"
                >
                    <X className="w-5 h-5" />
                </button>
             </div>
          </div>

          {/* Overlay grid for "tactical" look */}
          <div className="absolute inset-0 pointer-events-none opacity-20 bg-[linear-gradient(rgba(0,255,65,0.05)_1px,transparent_1px),linear-gradient(90deg,rgba(0,255,65,0.05)_1px,transparent_1px)] bg-[size:20px_20px]"></div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Terminal, Copy, Check } from 'lucide-react';
import { AnalysisResult, AppState } from '../types';

interface AnalysisViewProps {
  state: AppState;
  result: AnalysisResult | null;
  error: string | null;
}

export const AnalysisView: React.FC<AnalysisViewProps> = ({ state, result, error }) => {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = () => {
    if (result?.text) {
      navigator.clipboard.writeText(result.text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  if (state === AppState.IDLE && !result) {
    return (
      <div className="h-full min-h-[300px] flex flex-col items-center justify-center text-recon-muted border border-recon-gray/30 rounded-lg bg-recon-dark/30 p-8">
        <Terminal className="w-12 h-12 mb-4 opacity-50" />
        <p className="font-mono text-sm text-center">AWAITING INTEL...</p>
        <p className="text-xs text-center mt-2 opacity-50 max-w-xs">Upload an image to begin tactical analysis sequence.</p>
      </div>
    );
  }

  if (state === AppState.ANALYZING) {
    return (
      <div className="h-full min-h-[300px] relative overflow-hidden rounded-lg border border-recon-accent/30 bg-recon-dark flex flex-col items-center justify-center">
        {/* Scanning Animation */}
        <div className="scan-line z-10"></div>

        <div className="flex flex-col items-center space-y-4 z-20">
            <div className="relative">
                <div className="w-16 h-16 border-4 border-recon-gray rounded-full"></div>
                <div className="w-16 h-16 border-4 border-recon-accent rounded-full border-t-transparent animate-spin absolute top-0 left-0"></div>
            </div>
            <div className="font-mono text-recon-accent text-sm animate-pulse">
                PROCESSING INTEL...
            </div>
            <div className="font-mono text-xs text-recon-muted">
                ESTABLISHING NEURAL UPLINK
            </div>
        </div>

        {/* Background text scrolling effect */}
        <div className="absolute inset-0 opacity-10 font-mono text-[10px] leading-3 overflow-hidden text-recon-accent select-none pointer-events-none p-2 break-all">
            {Array(100).fill("010101101 ANALYZING SEGMENT 0xFF... ").join(" ")}
        </div>
      </div>
    );
  }

  if (state === AppState.ERROR || error) {
    return (
      <div className="h-full min-h-[300px] flex flex-col items-center justify-center text-red-500 border border-red-900/50 rounded-lg bg-red-900/10 p-8">
        <div className="text-4xl mb-4">⚠️</div>
        <h3 className="font-mono font-bold text-lg mb-2">SYSTEM FAILURE</h3>
        <p className="text-sm font-mono text-center opacity-80">{error || "Unknown Error"}</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col border border-recon-gray rounded-lg bg-recon-dark overflow-hidden shadow-2xl shadow-black/50">
      <div className="flex items-center justify-between px-4 py-3 border-b border-recon-gray bg-recon-gray/20">
        <div className="flex items-center space-x-2">
            <div className="w-2 h-2 rounded-full bg-recon-accent"></div>
            <span className="text-xs font-mono font-bold text-recon-text tracking-wider">ANALYSIS REPORT</span>
        </div>
        <div className="flex items-center space-x-3">
             <span className="text-[10px] font-mono text-recon-muted">{result?.timestamp}</span>
             <button 
                onClick={handleCopy}
                className="text-recon-muted hover:text-recon-accent transition-colors"
                title="Copy Report"
             >
                {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
             </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 font-mono text-sm leading-relaxed text-gray-300">
        <ReactMarkdown 
            components={{
                h1: ({node, ...props}) => <h1 className="text-xl font-bold text-recon-accent mb-4 border-b border-recon-accent/30 pb-2 uppercase tracking-wide" {...props} />,
                h2: ({node, ...props}) => <h2 className="text-lg font-bold text-white mb-3 mt-6 uppercase" {...props} />,
                h3: ({node, ...props}) => <h3 className="text-md font-bold text-gray-200 mb-2 mt-4" {...props} />,
                p: ({node, ...props}) => <p className="mb-4 text-justify" {...props} />,
                ul: ({node, ...props}) => <ul className="list-disc list-inside mb-4 space-y-1 text-gray-400" {...props} />,
                li: ({node, ...props}) => <li className="ml-4" {...props} />,
                strong: ({node, ...props}) => <strong className="text-recon-accent font-bold" {...props} />,
                code: ({node, ...props}) => <code className="bg-recon-gray/50 px-1 py-0.5 rounded text-xs" {...props} />,
            }}
        >
            {result?.text || ""}
        </ReactMarkdown>
      </div>

      <div className="px-4 py-2 border-t border-recon-gray bg-recon-black text-[10px] text-recon-muted font-mono flex justify-between">
         <span>CONFIDENCE: HIGH</span>
         <span>SECURE CONNECTION</span>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { Header } from './components/Header';
import { FileUploader } from './components/FileUploader';
import { AnalysisView } from './components/AnalysisView';
import { FileData, AppState, AnalysisResult } from './types';
import { analyzeContent } from './services/geminiService';
import { ArrowRight, RefreshCw } from 'lucide-react';

const App: React.FC = () => {
  const [fileData, setFileData] = useState<FileData | null>(null);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [promptText, setPromptText] = useState("");

  const handleFileSelect = useCallback((data: FileData) => {
    setFileData(data);
    setAppState(AppState.IDLE);
    setAnalysisResult(null);
    setError(null);
  }, []);

  const handleClear = useCallback(() => {
    setFileData(null);
    setAppState(AppState.IDLE);
    setAnalysisResult(null);
    setError(null);
    setPromptText("");
  }, []);

  const runAnalysis = async () => {
    if (!fileData) return;

    setAppState(AppState.ANALYZING);
    setError(null);

    try {
      const text = await analyzeContent(fileData.base64, fileData.mimeType, promptText);
      setAnalysisResult({
        text,
        timestamp: new Date().toLocaleTimeString(),
      });
      setAppState(AppState.COMPLETE);
    } catch (err: any) {
      setAppState(AppState.ERROR);
      setError(err.message || "Failed to analyze content. Ensure API key is valid.");
    }
  };

  return (
    <div className="min-h-screen bg-recon-black text-white font-sans selection:bg-recon-accent selection:text-black">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">

          {/* Left Column: Input & Controls */}
          <div className="lg:col-span-5 flex flex-col space-y-6">
            <div className="bg-recon-dark/50 border border-recon-gray rounded-lg p-6 shadow-lg backdrop-blur-sm">
              <div className="flex items-center justify-between mb-4">
                 <h2 className="text-lg font-mono font-bold text-recon-accent tracking-wide">
                   SOURCE INTEL
                 </h2>
                 <div className="h-px bg-recon-gray flex-grow ml-4"></div>
              </div>

              <FileUploader 
                onFileSelect={handleFileSelect} 
                selectedFile={fileData} 
                onClear={handleClear}
                disabled={appState === AppState.ANALYZING}
              />
            </div>

            <div className="bg-recon-dark/50 border border-recon-gray rounded-lg p-6 shadow-lg flex-grow flex flex-col">
               <div className="flex items-center justify-between mb-4">
                 <h2 className="text-lg font-mono font-bold text-recon-accent tracking-wide">
                   DIRECTIVES
                 </h2>
                 <div className="h-px bg-recon-gray flex-grow ml-4"></div>
              </div>

               <div className="space-y-4 flex-grow">
                 <label className="block text-xs font-mono text-gray-400 mb-1">
                   SPECIAL INSTRUCTIONS (OPTIONAL)
                 </label>
                 <textarea
                    value={promptText}
                    onChange={(e) => setPromptText(e.target.value)}
                    placeholder="e.g., Identify all vehicles in the image, or summarize the document text..."
                    className="w-full bg-black/40 border border-recon-gray rounded-md p-3 text-sm font-mono text-gray-300 focus:border-recon-accent focus:ring-1 focus:ring-recon-accent outline-none resize-none h-32 transition-all"
                    disabled={appState === AppState.ANALYZING}
                 />
               </div>

               <div className="mt-6">
                 <button
                    onClick={runAnalysis}
                    disabled={!fileData || appState === AppState.ANALYZING}
                    className={`
                      w-full py-4 px-6 rounded-md font-mono font-bold text-sm tracking-wider uppercase
                      flex items-center justify-center space-x-2
                      transition-all duration-200 transform
                      ${!fileData || appState === AppState.ANALYZING 
                        ? 'bg-recon-gray text-gray-500 cursor-not-allowed' 
                        : 'bg-recon-accent text-black hover:bg-green-400 hover:scale-[1.02] shadow-[0_0_15px_rgba(0,255,65,0.4)]'}
                    `}
                 >
                    {appState === AppState.ANALYZING ? (
                        <>
                            <RefreshCw className="w-5 h-5 animate-spin" />
                            <span>EXECUTING...</span>
                        </>
                    ) : (
                        <>
                            <span>INITIATE ANALYSIS</span>
                            <ArrowRight className="w-5 h-5" />
                        </>
                    )}
                 </button>
               </div>
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-7 h-[600px] lg:h-auto">
             <AnalysisView 
                state={appState} 
                result={analysisResult} 
                error={error} 
             />
          </div>

        </div>
      </main>

      {/* Decorative background elements */}
      <div className="fixed top-20 left-10 w-64 h-64 bg-recon-accent/5 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="fixed bottom-10 right-10 w-96 h-96 bg-blue-500/5 rounded-full blur-[100px] pointer-events-none"></div>
    </div>
  );
};

export default App;

