import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { MODEL_NAME, SYSTEM_INSTRUCTION } from "../constants";
import { PitchParams } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generatePitch = async (params: PitchParams): Promise<string> => {
  try {
    const prompt = `
      Write a cold email to ${params.companyName}, a company in the ${params.industry} space.
      My skills: ${params.userSkills}.
      Tone: ${params.tone}.

      Focus on how my skills specifically solve problems for their industry. 
      Keep it under 150 words.
    `;

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.8, // Slightly creative for sales copy
      },
    });

    return response.text || "Could not generate pitch. Try again.";
  } catch (error) {
    console.error("Recon Intelligence Error:", error);
    throw error;
  }
};

