import React, { useState } from 'react';
import { Target, Send, Loader2, Sparkles, Copy, Check } from 'lucide-react';
import { Company, PitchParams } from '../types';
import { generatePitch } from '../services/geminiService';

interface IntelligencePaneProps {
  company: Company | null;
}

export const IntelligencePane: React.FC<IntelligencePaneProps> = ({ company }) => {
  const [skills, setSkills] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedPitch, setGeneratedPitch] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    if (!company || !skills) return;

    setIsGenerating(true);
    setGeneratedPitch(null);
    try {
      const result = await generatePitch({
        companyName: company.name,
        industry: company.industry,
        userSkills: skills,
        tone: 'Professional'
      });
      setGeneratedPitch(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = () => {
    if (generatedPitch) {
      navigator.clipboard.writeText(generatedPitch);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  if (!company) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-neutral-400 animate-fade-in">
        <div className="w-16 h-16 rounded-2xl bg-neutral-100 dark:bg-neutral-900 flex items-center justify-center mb-4">
          <Target className="w-8 h-8 opacity-20" />
        </div>
        <h3 className="text-sm font-semibold text-neutral-900 dark:text-white mb-1">Ready to Scout</h3>
        <p className="text-xs max-w-xs text-center leading-relaxed">Select a company from the list to analyze their needs and draft a strategy.</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col gap-6 animate-fade-in">

      {/* The Scout Card */}
      <section className="glass-panel rounded-2xl border border-neutral-200 dark:border-white/10 bg-white/50 dark:bg-neutral-900/50 p-6 shadow-soft">
        <div className="flex items-center gap-2 mb-4">
           <div className="p-1.5 rounded-lg bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400">
             <Target className="w-4 h-4" />
           </div>
           <div>
             <h3 className="text-sm font-bold text-neutral-900 dark:text-white">The Scout</h3>
             <p className="text-[10px] text-neutral-500">Intelligence Brief</p>
           </div>
        </div>

        <div className="space-y-4">
          <div>
            <span className="text-xs font-medium text-neutral-500 uppercase tracking-wider">Mission</span>
            <p className="mt-1 text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
              {company.description}
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="p-3 rounded-xl bg-neutral-50 dark:bg-white/5 border border-neutral-100 dark:border-white/5">
              <span className="text-[10px] font-medium text-neutral-400 uppercase">Recent Intel</span>
              <p className="mt-1 text-xs font-medium text-neutral-800 dark:text-neutral-200">"{company.recentWork}"</p>
            </div>
            <div className="p-3 rounded-xl bg-neutral-50 dark:bg-white/5 border border-neutral-100 dark:border-white/5">
              <span className="text-[10px] font-medium text-neutral-400 uppercase">Suspected Needs</span>
              <div className="flex flex-wrap gap-1 mt-1">
                {company.needs.map(need => (
                  <span key={need} className="text-[10px] px-1.5 py-0.5 rounded bg-white dark:bg-white/10 border border-neutral-200 dark:border-white/5 text-neutral-600 dark:text-neutral-300">
                    {need}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* The Pitcher Card */}
      <section className="flex-1 glass-panel flex flex-col rounded-2xl border border-neutral-200 dark:border-white/10 bg-white/50 dark:bg-neutral-900/50 p-6 shadow-soft min-h-[400px]">
         <div className="flex items-center gap-2 mb-4">
           <div className="p-1.5 rounded-lg bg-accent-dim text-accent">
             <Send className="w-4 h-4" />
           </div>
           <div>
             <h3 className="text-sm font-bold text-neutral-900 dark:text-white">The Pitcher</h3>
             <p className="text-[10px] text-neutral-500">Outreach Generator</p>
           </div>
        </div>

        <div className="space-y-2 mb-4">
          <label className="text-xs font-medium text-neutral-500 ml-1">Your Capability (Skills)</label>
          <div className="relative">
             <input 
                type="text" 
                value={skills}
                onChange={(e) => setSkills(e.target.value)}
                placeholder="e.g. Documentary editing, 3D product renders..." 
                className="w-full bg-white dark:bg-neutral-950/50 border border-neutral-200 dark:border-white/10 rounded-xl px-4 py-3 text-sm text-neutral-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-accent transition-all"
             />
             <button 
                onClick={handleGenerate}
                disabled={!skills || isGenerating}
                className="absolute right-2 top-2 p-1.5 rounded-lg bg-accent text-white hover:bg-accent-glow disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
             >
                {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
             </button>
          </div>
        </div>

        <div className="flex-1 relative rounded-xl bg-white dark:bg-neutral-950 border border-neutral-200 dark:border-white/10 p-4 font-mono text-sm leading-relaxed overflow-hidden group">
