export const generatePitch = async (params: PitchParams): Promise<string> => {
  try {
    // We now call our own Cloudflare backend function
    const response = await fetch('/api/pitch', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(params),
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `Server error: ${response.status}`);
    }

    const data = await response.json();
    return data.text;
  } catch (error) {
    console.error("Recon Intelligence Error:", error);
    throw error;
  }
};

import { GoogleGenAI } from "@google/genai";

// We redefine constants here to ensure the serverless function is self-contained
// and doesn't rely on frontend build path aliases.
const MODEL_NAME = 'gemini-3-flash-preview';
const SYSTEM_INSTRUCTION = `
You are Recon, an elite sales strategist for high-end creative freelancers (cinematographers, editors, designers).
Your goal is to write cold emails that convert.
Input: Company Name, Industry, User's Skills, Desired Tone.
Output: A concise, high-impact cold email.

Rules:
1. Subject line must be intriguing but not clickbait.
2. Opening line must be hyper-personalized based on the company's industry.
3. No fluff. Get straight to the value proposition.
4. Call to action should be low friction (e.g., "Worth a chat?").
5. Return ONLY the email body (including subject line at the top formatted as "Subject: ...").
`;

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    const { request, env } = context;

    // 1. Security Check
    if (!env.API_KEY) {
      return new Response(JSON.stringify({ error: "API Key not configured on server" }), {
        status: 500,
        headers: { "Content-Type": "application/json" },
      });
    }

    // 2. Parse Input
    const params = await request.json();
    const { companyName, industry, userSkills, tone } = params;

    if (!companyName || !industry || !userSkills) {
      return new Response(JSON.stringify({ error: "Missing required fields" }), {
        status: 400,
        headers: { "Content-Type": "application/json" },
      });
    }

    // 3. Initialize AI (Server-side)
    const ai = new GoogleGenAI({ apiKey: env.API_KEY });

    // 4. Generate Content
    const prompt = `
      Write a cold email to ${companyName}, a company in the ${industry} space.
      My skills: ${userSkills}.
      Tone: ${tone}.

      Focus on how my skills specifically solve problems for their industry. 
      Keep it under 150 words.
    `;

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.8,
      },
    });

    const generatedText = response.text || "Could not generate pitch.";

    // 5. Return Result
    return new Response(JSON.stringify({ text: generatedText }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });

  } catch (error: any) {
    console.error("Backend Error:", error);
    return new Response(JSON.stringify({ error: error.message || "Internal Server Error" }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
};

import { GoogleGenAI } from "@google/genai";

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    const { request, env } = context;

    if (!env.API_KEY) {
      return new Response(JSON.stringify({ error: "API Key not configured" }), { status: 500 });
    }

    const { industry, city } = await request.json();

    if (!industry || !city) {
      return new Response(JSON.stringify({ error: "Industry and City are required" }), { status: 400 });
    }

    const ai = new GoogleGenAI({ apiKey: env.API_KEY });

    // Maps Grounding is supported on gemini-2.5-flash
    const model = 'gemini-2.5-flash';

    // We cannot use JSON mode with Maps tool, so we ask for a strict separator format
    const prompt = `
      Find 5 active ${industry} companies or agencies in ${city}.

      For each company, provide:
      1. Name
      2. A brief 1-sentence description of what they do.
      3. A specific 'need' or 'opportunity' a freelancer could pitch for (e.g., "Website redesign", "Video marketing").

      Format your output as a strict list where each line is:
      Name | Description | Potential Need

      Do not add numbering or bullet points. Just the data separated by pipes (|).
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
        temperature: 0.5,
      },
    });

    const text = response.text || "";

    // Parse the pipe-separated text response
    const leads = text
      .split('\n')
      .map(line => line.trim())
      .filter(line => line.includes('|'))
      .map((line, index) => {
        const [name, description, need] = line.split('|').map(s => s.trim());
        return {
          id: `gen-${Date.now()}-${index}`,
          name: name || "Unknown Company",
          website: "Search to find URL", // Maps grounding returns URLs in metadata, but simplified here for text parsing
          industry: industry,
          status: 'New',
          description: description || "No description available",
          recentWork: "Identified via active search",
          needs: [need || "General Creative Services"]
        };
      });

    return new Response(JSON.stringify({ leads }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    console.error("Leads API Error:", error);
    return new Response(JSON.stringify({ error: error.message }), { status: 500 });
  }
};

