import { PitchParams, Company } from "../types";

export const generatePitch = async (params: PitchParams): Promise<string> => {
  try {
    const response = await fetch('/api/pitch', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(params),
    });

    const contentType = response.headers.get("content-type");
    if (contentType && contentType.includes("application/json")) {
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || `Pitch Generation Failed: ${response.statusText}`);
      }
      return data.text;
    } else {
       const text = await response.text();
       console.error("Pitch API Error (Non-JSON):", text);
       throw new Error(`Server Error (${response.status}). Check console for details.`);
    }

  } catch (error) {
    console.error("Recon Pitch Error:", error);
    throw error;
  }
};

export const findLeads = async (industry: string, city: string, excludeNames: string[] = []): Promise<Company[]> => {
  try {
    const response = await fetch('/api/leads', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ industry, city, excludeNames }),
    });

    const contentType = response.headers.get("content-type");
    if (contentType && contentType.includes("application/json")) {
        const data = await response.json();
        if (!response.ok) {
            throw new Error(data.error || `Discovery Failed: ${response.statusText}`);
        }
        return data.leads || [];
    } else {
        // Handle non-JSON response (e.g., 404 HTML page or 500 crash page)
        const text = await response.text();
        console.error("Leads API Error (Non-JSON):", text);

        let msg = `Server Error (${response.status})`;
        if (response.status === 404) msg = "API Endpoint Not Found (404). If running locally, use 'wrangler pages dev'.";
        else if (response.status === 500) msg = "Internal Server Error (500). Check Cloudflare logs.";

        throw new Error(msg);
    }

  } catch (error) {
    console.error("Recon Discovery Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Header } from './components/Header';
import { SearchPane } from './components/SearchPane';
import { IntelligencePane } from './components/IntelligencePane';
import { Company } from './types';
import { findLeads } from './services/geminiService';

const App: React.FC = () => {
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [companies, setCompanies] = useState<Company[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  // Keep track of current search params for "Load More"
  const currentSearchRef = useRef({ industry: '', city: '' });

  // Initialize theme
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Mouse tracking for spotlight effect
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    const x = e.clientX;
    const y = e.clientY;
    document.documentElement.style.setProperty('--mouse-x', `${x}px`);
    document.documentElement.style.setProperty('--mouse-y', `${y}px`);
  }, []);

  const handleSearch = async (industry: string, city: string) => {
    if (!industry || !city) return;

    currentSearchRef.current = { industry, city };
    setIsSearching(true);
    setCompanies([]); // Clear previous results for new search

    try {
      const newLeads = await findLeads(industry, city);
      setCompanies(newLeads);
      if (newLeads.length > 0) {
        setSelectedCompanyId(null); 
      } else {
        alert(`No leads found for ${industry} in ${city}. Try a broader search.`);
      }
    } catch (error: any) {
      console.error("Search failed", error);
      alert(error.message || "Could not find leads. Please check API Key configuration.");
    } finally {
      setIsSearching(false);
    }
  };

  const handleLoadMore = async () => {
    const { industry, city } = currentSearchRef.current;
    if (!industry || !city) return;

    setIsSearching(true);
    try {
      // Pass existing names to exclude them from next batch
      const existingNames = companies.map(c => c.name);
      const moreLeads = await findLeads(industry, city, existingNames);

      if (moreLeads.length === 0) {
        alert("No more unique leads found in this area.");
      } else {
        setCompanies(prev => [...prev, ...moreLeads]);
      }
    } catch (error: any) {
      console.error("Load more failed", error);
      alert(error.message || "Failed to load more leads.");
    } finally {
      setIsSearching(false);
    }
  };

  const selectedCompany = companies.find(c => c.id === selectedCompanyId) || null;

  return (
    <div 
      onMouseMove={handleMouseMove}
      className="min-h-screen bg-neutral-50 dark:bg-neutral-950 transition-colors duration-400 selection:bg-accent selection:text-white overflow-hidden flex flex-col relative"
    >

      {/* Background Ambience & Spotlight */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
         {/* Static Ambience */}
        {isDarkMode ? (
           <div className="absolute -top-[20%] -left-[10%] w-[50%] h-[50%] rounded-full bg-accent/5 blur-[120px] transition-opacity duration-1000"></div>
        ) : (
           <div className="absolute -top-[20%] -left-[10%] w-[50%] h-[50%] rounded-full bg-accent/10 blur-[120px] transition-opacity duration-1000"></div>
        )}

        {/* Dynamic Interactive Spotlight */}
        <div className="absolute inset-0 spotlight-bg opacity-100 transition-opacity duration-500"></div>
      </div>

      <div className="relative z-10 flex flex-col h-full">
        <Header isDarkMode={isDarkMode} toggleTheme={toggleTheme} />

        <main className="flex-1 max-w-screen-2xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-6 h-[calc(100vh-64px)] overflow-hidden">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">

            {/* Left: Search & Leads */}
            <div className="lg:col-span-4 h-full overflow-hidden flex flex-col">
              <SearchPane 
                  companies={companies} 
                  selectedCompanyId={selectedCompanyId}
                  onSelectCompany={setSelectedCompanyId}
                  onSearch={handleSearch}
                  onLoadMore={handleLoadMore}
                  isSearching={isSearching}
              />
            </div>

            {/* Right: Intelligence */}
            <div className="hidden lg:block lg:col-span-8 h-full overflow-hidden">
              <IntelligencePane company={selectedCompany} />
            </div>

            {/* Mobile View Handling (Stacking) */}
            {selectedCompanyId && (
              <div className="lg:hidden fixed inset-0 z-40 bg-neutral-50 dark:bg-neutral-950 flex flex-col animate-fade-in-up">
                  <div className="p-4 border-b border-neutral-200 dark:border-white/10 flex items-center bg-white/50 dark:bg-neutral-900/50 backdrop-blur-md">
                      <button 
                          onClick={() => setSelectedCompanyId(null)}
                          className="text-sm font-medium text-neutral-500 hover:text-neutral-900 dark:hover:text-white transition-colors"
                      >
                          ← Back to Search
                      </button>
                  </div>
                  <div className="flex-1 p-4 overflow-y-auto">
                      <IntelligencePane company={selectedCompany} />
                  </div>
              </div>
            )}

          </div>
        </main>
      </div>
    </div>
  );
};

