import React, { useRef, useState } from 'react';
import { Upload, X } from 'lucide-react';
import { ACCEPTED_IMAGE_TYPES } from '../constants';
import { FileData } from '../types';

interface FileUploaderProps {
  onFileSelect: (fileData: FileData) => void;
  selectedFile: FileData | null;
  onClear: () => void;
  disabled: boolean;
}

export const FileUploader: React.FC<FileUploaderProps> = ({ onFileSelect, selectedFile, onClear, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = (file: File) => {
    if (!file) return;

    // Check type roughly
    if (!file.type.startsWith('image/')) {
        alert("System currently optimized for Image Analysis.");
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target?.result as string;
      const base64 = result.split(',')[1];
      onFileSelect({
        file,
        previewUrl: result,
        base64,
        mimeType: file.type
      });
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  return (
    <div className="w-full">
      {!selectedFile ? (
        <div
          onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={handleDrop}
          onClick={() => !disabled && fileInputRef.current?.click()}
          className={`
            relative group cursor-pointer 
            border-2 border-dashed rounded-lg p-12 
            transition-all duration-300 ease-in-out
            flex flex-col items-center justify-center
            ${isDragging 
              ? 'border-accent bg-accent-dim' 
              : 'border-neutral-700 hover:border-neutral-500 bg-neutral-900/50 hover:bg-neutral-800/20'}
            ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
          `}
        >
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleChange}
            accept={ACCEPTED_IMAGE_TYPES}
            className="hidden"
            disabled={disabled}
          />

          <div className={`p-4 rounded-full bg-neutral-800 mb-4 group-hover:scale-110 transition-transform ${isDragging ? 'text-accent' : 'text-neutral-400'}`}>
            <Upload className="w-8 h-8" />
          </div>

          <h3 className="text-lg font-mono font-medium text-neutral-300 mb-1">
            Drop Image Here
          </h3>
          <p className="text-xs text-neutral-500 font-mono">
            SUPPORTED: PNG, JPG, WEBP
          </p>

          {/* Decorative corners */}
          <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-neutral-700 group-hover:border-accent transition-colors"></div>
          <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-neutral-700 group-hover:border-accent transition-colors"></div>
          <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-neutral-700 group-hover:border-accent transition-colors"></div>
          <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-neutral-700 group-hover:border-accent transition-colors"></div>
        </div>
      ) : (
        <div className="relative rounded-lg overflow-hidden border border-neutral-700 bg-neutral-900 group">
          <img 
            src={selectedFile.previewUrl} 
            alt="Preview" 
            className="w-full h-64 md:h-96 object-contain bg-black/50"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-4">
             <div className="flex justify-between items-end">
                <div className="font-mono text-xs text-accent">
                    <p>FILE: {selectedFile.file.name}</p>
                    <p>SIZE: {(selectedFile.file.size / 1024).toFixed(2)} KB</p>
                </div>
                <button 
                    onClick={(e) => { e.stopPropagation(); onClear(); }}
                    disabled={disabled}
                    className="p-2 bg-red-500/20 hover:bg-red-500/40 text-red-500 rounded-full border border-red-500/50 transition-colors"
                >
                    <X className="w-5 h-5" />
                </button>
             </div>
          </div>

          {/* Overlay grid */}
          <div className="absolute inset-0 pointer-events-none opacity-20 bg-[linear-gradient(rgba(20,184,166,0.05)_1px,transparent_1px),linear-gradient(90deg,rgba(20,184,166,0.05)_1px,transparent_1px)] bg-[size:20px_20px]"></div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Header } from './components/Header';
import { SearchPane } from './components/SearchPane';
import { IntelligencePane } from './components/IntelligencePane';
import { Sidebar } from './components/Sidebar';
import { Company, SearchMode, SearchParams } from './types';
import { findLeads } from './services/geminiService';
import { Menu, X, ChevronRight } from 'lucide-react';

const App: React.FC = () => {
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  // State for Live Results vs Saved Targets
  const [searchResults, setSearchResults] = useState<Company[]>([]);
  const [savedCompanies, setSavedCompanies] = useState<Company[]>(() => {
    // Basic persistence
    const saved = localStorage.getItem('recon_saved_targets');
    return saved ? JSON.parse(saved) : [];
  });

  // Pre-fetching State
  const [nextBatch, setNextBatch] = useState<Company[]>([]);
  const [isPrefetching, setIsPrefetching] = useState(false);

  const [isSearching, setIsSearching] = useState(false);
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);

  const currentSearchParamsRef = useRef<SearchParams | null>(null);

  // Abort Controller Ref to handle cancellation
  const abortControllerRef = useRef<AbortController | null>(null);

  // Initialize theme
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
    }
  }, [isDarkMode]);

  // Persist Saved Companies
  useEffect(() => {
    localStorage.setItem('recon_saved_targets', JSON.stringify(savedCompanies));
  }, [savedCompanies]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Mouse tracking
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    const x = e.clientX;
    const y = e.clientY;
    document.documentElement.style.setProperty('--mouse-x', `${x}px`);
    document.documentElement.style.setProperty('--mouse-y', `${y}px`);
  }, []);

  // BACKGROUND TASK: Prefetch the next 5 leads
  const prefetchNextBatch = async (currentResults: Company[], params: SearchParams) => {
    if (params.mode === 'lookup') return; // Don't prefetch for single lookups

    setIsPrefetching(true);
    try {
        // Exclude everything we currently see AND everything saved
        const excludeNames = [...currentResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
        const nextParams = { ...params, excludeNames };

        // We use the same abort controller logic? 
        // No, we want prefetch to be cancelable if a NEW search starts, but not if just idling.
        // If a new search starts, abortControllerRef.current.abort() is called below, which kills this too if we share the controller.

        const nextLeads = await findLeads(nextParams, abortControllerRef.current?.signal);
        setNextBatch(nextLeads);
    } catch (error: any) {
        if (error.name !== 'AbortError') {
            console.log("Prefetch suspended or failed (non-critical).");
        }
    } finally {
        setIsPrefetching(false);
    }
  };

  const handleSearch = async (mode: SearchMode, p1: string, p2: string) => {
    // 1. STOP EVERYTHING: Abort any ongoing search or pre-fetch
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
    // 2. Create new controller for this session
    abortControllerRef.current = new AbortController();

    setIsSearching(true);
    setSearchResults([]); 
    setNextBatch([]); // Clear buffer
    setSelectedCompanyId(null);

    const params: SearchParams = {
        mode,
        industry: mode === 'discovery' ? p1 : undefined,
        city: p2,
        companyName: mode === 'lookup' ? p1 : undefined,
        excludeNames: savedCompanies.map(c => c.name)
    };
    currentSearchParamsRef.current = params;

    try {
      const newLeads = await findLeads(params, abortControllerRef.current.signal);
      setSearchResults(newLeads);

      if (newLeads.length === 0) {
        alert(`No leads found. Try a broader search.`);
      } else {
        // 3. SUCCESS? IMMEDIATELY START PRE-FETCHING NEXT BATCH
        // We pass 'newLeads' directly because state updates are async
        prefetchNextBatch(newLeads, params);
      }
    } catch (error: any) {
      if (error.name === 'AbortError') {
          console.log("Search aborted by user.");
      } else {
          console.error("Search failed", error);
          alert(error.message || "Could not find leads.");
      }
    } finally {
      // Only turn off searching spinner if we aren't aborted (which implies a new search started)
      if (!abortControllerRef.current?.signal.aborted) {
          setIsSearching(false);
      }
    }
  };

  const handleLoadMore = async () => {
    if (!currentSearchParamsRef.current || currentSearchParamsRef.current.mode === 'lookup') return;

    // STRATEGY: Instant Load if buffer is ready
    if (nextBatch.length > 0) {
        const newBatch = [...nextBatch];
        setNextBatch([]); // Clear buffer immediately
        setSearchResults(prev => {
            const updated = [...prev, ...newBatch];
            // Trigger NEXT prefetch based on updated list
            prefetchNextBatch(updated, currentSearchParamsRef.current!); 
            return updated;
        });
        return;
    }

    // Fallback: Buffer wasn't ready (network slow?), so we show spinner and wait
    setIsSearching(true);
    try {
      const excludeNames = [...searchResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
      const params: SearchParams = { ...currentSearchParamsRef.current, excludeNames };

      const moreLeads = await findLeads(params, abortControllerRef.current?.signal);

      if (moreLeads.length === 0) {
        alert("No more unique leads found in this area.");
      } else {
        setSearchResults(prev => {
            const updated = [...prev, ...moreLeads];
            prefetchNextBatch(updated, currentSearchParamsRef.current!);
            return updated;
        });
      }
    } catch (error: any) {
       if (error.name !== 'AbortError') {
          alert(error.message || "Failed to load more leads.");
       }
    } finally {
      setIsSearching(false);
    }
  };

  const toggleSaveCompany = (company: Company) => {
    if (savedCompanies.some(c => c.id === company.id)) {
        // Remove
        setSavedCompanies(prev => prev.filter(c => c.id !== company.id));
    } else {
        // Add
        const newCompany = { ...company, status: 'Saved' as const };
        setSavedCompanies(prev => [newCompany, ...prev]);
    }
  };

  const removeSavedCompany = (id: string) => {
    setSavedCompanies(prev => prev.filter(c => c.id !== id));
    if (selectedCompanyId === id) setSelectedCompanyId(null);
  };

  // Determine which company is currently active
  const selectedCompany = 
    searchResults.find(c => c.id === selectedCompanyId) || 
    savedCompanies.find(c => c.id === selectedCompanyId) || 
    null;

  return (
    <div 
      onMouseMove={handleMouseMove}
      className="h-screen bg-neutral-50 dark:bg-neutral-950 transition-colors duration-400 overflow-hidden flex flex-col relative"
    >
      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div className={`absolute -top-[20%] -left-[10%] w-[50%] h-[50%] rounded-full blur-[120px] transition-opacity duration-1000 ${isDarkMode ? 'bg-accent/5' : 'bg-accent/10'}`}></div>
        <div className="absolute inset-0 spotlight-bg opacity-100 transition-opacity duration-500"></div>
      </div>

      <div className="relative z-10 flex flex-col h-full">
        <Header isDarkMode={isDarkMode} toggleTheme={toggleTheme} />

        <main className="flex-1 w-full max-w-screen-2xl mx-auto flex overflow-hidden">

          {/* Sidebar - Desktop */}
          <div className="hidden lg:block w-64 h-full shrink-0">
             <Sidebar 
                savedCompanies={savedCompanies}
                onSelectCompany={(c) => setSelectedCompanyId(c.id)}
                selectedCompanyId={selectedCompanyId}
                onRemoveCompany={removeSavedCompany}
             />
          </div>

           {/* Sidebar - Mobile Drawer */}
           {showMobileSidebar && (
              <div className="fixed inset-0 z-50 lg:hidden flex">
                  <div className="w-64 h-full bg-neutral-900 shadow-2xl animate-fade-in">
                     <Sidebar 
                        savedCompanies={savedCompanies}
                        onSelectCompany={(c) => { setSelectedCompanyId(c.id); setShowMobileSidebar(false); }}
                        selectedCompanyId={selectedCompanyId}
                        onRemoveCompany={removeSavedCompany}
                     />
                  </div>
                  <div className="flex-1 bg-black/50 backdrop-blur-sm" onClick={() => setShowMobileSidebar(false)}></div>
              </div>
           )}

          <div className="flex-1 flex flex-col lg:flex-row min-w-0">

            {/* Mobile Sidebar Toggle */}
            <div className="lg:hidden p-2 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-neutral-100/50 dark:bg-neutral-900/50">
               <button onClick={() => setShowMobileSidebar(true)} className="flex items-center gap-2 text-xs font-bold uppercase text-neutral-500">
                  <Menu className="w-4 h-4" /> Open Saved List
               </button>
               <span className="text-[10px] text-accent font-mono">{savedCompanies.length} SAVED</span>
            </div>

            {/* Middle: Live Search Results */}
            <div className={`
                flex-1 flex flex-col h-full min-w-0 border-r border-neutral-200 dark:border-white/5 bg-white/30 dark:bg-neutral-950/30
                ${selectedCompanyId ? 'hidden lg:flex' : 'flex'} 
            `}>
              <div className="p-4 h-full">
                <SearchPane 
                    companies={searchResults} 
                    selectedCompanyId={selectedCompanyId}
                    onSelectCompany={setSelectedCompanyId}
                    onSearch={handleSearch}
                    onLoadMore={handleLoadMore}
                    isSearching={isSearching}
                />
              </div>
            </div>

            {/* Right: Intelligence Pane (Dossier) */}
            <div className={`
                lg:w-[600px] xl:w-[700px] h-full flex-col bg-white/50 dark:bg-neutral-900/50 backdrop-blur-md
                ${selectedCompanyId ? 'flex fixed inset-0 z-40 lg:static lg:z-auto' : 'hidden lg:flex'}
            `}>
               {selectedCompanyId && (
                  <div className="lg:hidden p-4 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-white dark:bg-neutral-900">
                      <button 
                          onClick={() => setSelectedCompanyId(null)}
                          className="text-sm font-medium text-neutral-500 flex items-center gap-2"
                      >
                          <ChevronRight className="w-4 h-4 rotate-180" /> Back
                      </button>
                  </div>
               )}

               <div className="flex-1 h-full overflow-hidden p-4">
                  <IntelligencePane 
                      company={selectedCompany} 
                      onToggleSave={() => selectedCompany && toggleSaveCompany(selectedCompany)}
                      isSaved={!!selectedCompany && savedCompanies.some(c => c.id === selectedCompany.id)}
                  />
               </div>
            </div>

          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    if (typeof process === 'undefined') {
      (globalThis as any).process = { env: {} };
    }

    const { request, env } = context;
    const apiKey = env.API_KEY || (typeof process !== 'undefined' ? process.env.API_KEY : null);

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "Server Configuration Error: API Key missing." }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
      });
    }

    const { mode, industry, city, companyName, excludeNames } = await request.json();

    if (mode === 'lookup') {
        if (!companyName) return new Response(JSON.stringify({ error: "Company Name is required for lookup" }), { status: 400 });
    } else {
        if (!industry || !city) return new Response(JSON.stringify({ error: "Industry and City are required" }), { status: 400 });
    }

    const ai = new GoogleGenAI({ apiKey: apiKey });

    // Using Gemini 3 Flash Preview for optimal speed and search grounding support
    const model = 'gemini-3-flash-preview';

    const exclusionList = excludeNames && excludeNames.length > 0 ? excludeNames.join(', ') : "None";

    let prompt = '';

    const jsonStructure = `
    {
      "leads": [
        {
          "name": "string",
          "website": "string",
          "location": "string",
          "description": "string (Max 15 words)",
          "needs": ["string (Key needs only)"],
          "heroProduct": "string",
          "phone": "string (MUST TRY TO FIND - SEARCH HARD)",
          "email": "string (MUST TRY TO FIND - SEARCH HARD)",
          "socials": "string (Space separated URLs - REQUIRED)",
          "hotScore": number (0-100),
          "signals": [
            { 
               "type": "string", 
               "text": "string (Concise evidence)",
               "confidence": "High" | "Medium" | "Low"
            }
          ]
        }
      ]
    }
    `;

    // SYSTEM INSTRUCTION: Sets the baseline behavior to be aggressive about contacts
    const systemInstruction = `
      You are an expert Lead Generation AI agent.

      CORE DIRECTIVE: You MUST prioritize finding CONTACT INFORMATION (Phone, Email, Social Links) above all else.

      SEARCH RULES:
      1. Always search for "[Company] contact phone email".
      2. Always search for "[Company] facebook instagram linkedin" to find social profiles, as they often contain phone numbers/emails missing from websites.
      3. If a direct email is missing, look for "info@", "hello@", or "contact@" addresses on their homepage or social media.
      4. Do not return "N/A" for Phone or Email unless you have verified it does not exist on their Website, Facebook, AND Instagram.
    `;

    if (mode === 'lookup') {
        prompt = `
            DEEP OSINT TASK: Target "${companyName}" in "${city || 'any location'}".

            OBJECTIVE: Find confirmed contact details (Phone, Email, Socials).

            PROTOCOL:
            1. Search for official website.
            2. Search for "${companyName} contact email phone".
            3. Search for "${companyName} LinkedIn" or Facebook to find contact info in profiles.

            Return JSON only. Structure:
            ${jsonStructure}
        `;
    } else {
        prompt = `
            SCOUT MISSION: Find 5 ACTIVE ${industry} companies in ${city}.
            Exclude: ${exclusionList}.

            CRITICAL: For every lead found, you must perform a secondary search for their contact info.

            PROTOCOL:
            1. SEARCH: "${industry} companies ${city} directory".
            2. FOR EACH LEAD:
               - Search for "[Lead Name] ${city} phone email social media".
               - Check the snippets for phone numbers (look for local area codes).
               - Check the snippets for emails (look for @ symbol).

            Return JSON only. Structure:
            ${jsonStructure}
        `;
    }

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        tools: [
            { googleSearch: {} } 
        ],
        temperature: 0.4,
        systemInstruction: systemInstruction
      },
    });

    let text = response.text || "{}";

    // Robust JSON extraction
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        text = text.substring(firstBrace, lastBrace + 1);
    }

    let data;
    try {
        data = JSON.parse(text);
    } catch (e) {
        console.error("JSON Parse Error on text:", text);
        return new Response(JSON.stringify({ error: "Failed to parse AI response. Please try again." }), { 
            status: 500,
            headers: { "Content-Type": "application/json" }
        });
    }

    const leads = (data.leads || []).map((lead: any, index: number) => ({
        ...lead,
        id: `gen-${Date.now()}-${index}`,
        status: 'New',
        recentWork: lead.description, 
        website: lead.website || "N/A",
        phone: lead.phone || "N/A",
        email: lead.email || "N/A",
        socials: lead.socials || "N/A",
        signals: lead.signals || [],
        location: lead.location || city
    }));

    return new Response(JSON.stringify({ leads }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    console.error("Leads API Critical Error:", error);
    return new Response(JSON.stringify({ error: error.message || "Unknown Server Error" }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
    });
  }
};

import React, { useState } from 'react';
import { Target, Send, Loader2, Sparkles, Copy, Check, Bot, Phone, Mail, Award, Globe, Linkedin, Twitter, Facebook, Instagram, Youtube, Link as LinkIcon, Zap, TrendingUp, DollarSign, Newspaper, Edit3, Bookmark, ShieldCheck, MapPin, Briefcase } from 'lucide-react';
import { Company, Pitch } from '../types';
import { generatePitch } from '../services/geminiService';

interface IntelligencePaneProps {
  company: Company | null;
  onToggleSave: () => void;
  isSaved: boolean;
}

type Tab = 'overview' | 'insights' | 'outreach';

export const IntelligencePane: React.FC<IntelligencePaneProps> = ({ company, onToggleSave, isSaved }) => {
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [skills, setSkills] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedPitches, setGeneratedPitches] = useState<Pitch[]>([]);
  const [activePitchIndex, setActivePitchIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  React.useEffect(() => {
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
    setActiveTab('overview');
  }, [company?.id]);

  const handleGenerate = async () => {
    if (!company || !skills) return;

    setIsGenerating(true);
    setGeneratedPitches([]);
    try {
      // Pass the found signals to the pitcher for context
      const signalContext = company.signals.map(s => `${s.type}: ${s.text}`);

      const results = await generatePitch({
        companyName: company.name,
        industry: company.industry,
        userSkills: skills,
        tone: 'Professional',
        companySignals: signalContext
      });
      setGeneratedPitches(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getSignalIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('fund') || t.includes('money')) return <DollarSign className="w-3 h-3 text-emerald-500" />;
    if (t.includes('hir') || t.includes('team') || t.includes('growth')) return <TrendingUp className="w-3 h-3 text-blue-500" />;
    if (t.includes('news') || t.includes('press')) return <Newspaper className="w-3 h-3 text-purple-500" />;
    if (t.includes('loc') || t.includes('hq')) return <MapPin className="w-3 h-3 text-orange-500" />;
    return <ShieldCheck className="w-3 h-3 text-accent" />;
  };

  const getSocialLinks = () => {
    if (!company || !company.socials || company.socials === 'N/A' || company.socials === 'None') return [];

    // Split by spaces, commas, or newlines to handle various AI outputs
    return company.socials
      .split(/[\s,\n]+/)
      .map(s => s.trim())
      .filter(s => s.length > 0 && !s.toLowerCase().includes('n/a'))
      .map((rawLink, index) => {
        // Clean potential markdown or brackets formatting
        let url = rawLink.replace(/[\[\]()]/g, '');

        // Ensure protocol exists
        if (!url.startsWith('http')) {
            url = `https://${url}`;
        }

        // Basic validation: must include a dot and have minimal length to be a URL
        if (!url.includes('.') || url.length < 8) return null;

        let icon = <LinkIcon className="w-4 h-4" />;
        const lowerUrl = url.toLowerCase();

        if (lowerUrl.includes('linkedin')) icon = <Linkedin className="w-4 h-4" />;
        else if (lowerUrl.includes('twitter') || lowerUrl.includes('x.com')) icon = <Twitter className="w-4 h-4" />;
        else if (lowerUrl.includes('facebook')) icon = <Facebook className="w-4 h-4" />;
        else if (lowerUrl.includes('instagram')) icon = <Instagram className="w-4 h-4" />;
        else if (lowerUrl.includes('youtube')) icon = <Youtube className="w-4 h-4" />;

        return { url, icon, key: index };
      })
      .filter((link): link is { url: string; icon: JSX.Element; key: number } => link !== null);
  };

  if (!company) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-neutral-400 select-none">
        <div className="w-20 h-20 rounded-3xl bg-neutral-100 dark:bg-neutral-900/50 flex items-center justify-center mb-6 ring-1 ring-neutral-200 dark:ring-white/5">
          <Target className="w-8 h-8 opacity-20" />
        </div>
        <h3 className="text-base font-semibold text-neutral-900 dark:text-white mb-2">Company Selection Required</h3>
        <p className="text-sm max-w-xs text-center leading-relaxed opacity-60">Select a lead from the list or your saved items to view company details.</p>
      </div>
    );
  }

  const socialLinks = getSocialLinks();
  const currentPitch = generatedPitches[activePitchIndex];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-white/10 shadow-glass overflow-hidden">

      {/* Header */}
      <div className="p-6 border-b border-neutral-200 dark:border-white/5 bg-neutral-50/50 dark:bg-black/20">
         <div className="flex justify-between items-start mb-4">
             <div>
                 <h2 className="text-xl font-bold text-neutral-900 dark:text-white tracking-tight">{company.name}</h2>
                 <div className="flex items-center gap-2 text-xs text-neutral-500 mt-1">
                     <Briefcase className="w-3 h-3" />
                     <span>{company.industry}</span>
                     <span className="text-neutral-300 dark:text-neutral-700">•</span>
                     <MapPin className="w-3 h-3" />
                     <span>{company.location || "Unknown Location"}</span>
                 </div>
             </div>

             <button 
                onClick={onToggleSave}
                className={`p-2 rounded-lg border transition-all ${isSaved ? 'bg-accent/10 border-accent text-accent' : 'bg-white dark:bg-neutral-800 border-neutral-200 dark:border-white/10 text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                title={isSaved ? "Remove from List" : "Save to List"}
             >
                 <Bookmark className={`w-4 h-4 ${isSaved ? 'fill-accent' : ''}`} />
             </button>
         </div>

         {/* Stats Bar */}
         <div className="flex items-center gap-4">
             <div className="px-3 py-1.5 rounded-md bg-neutral-100 dark:bg-white/5 border border-neutral-200 dark:border-white/5 flex items-center gap-2">
                 <Zap className="w-3 h-3 text-amber-500" />
                 <span className="text-xs font-bold text-neutral-700 dark:text-neutral-300">Match: {company.hotScore}%</span>
             </div>
             <div className="flex gap-2">
                 {socialLinks.map(link => (
                     <a key={link.key} href={link.url} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        {link.icon}
                     </a>
                 ))}
                 {company.website !== 'N/A' && (
                     <a href={company.website.startsWith('http') ? company.website : `https://${company.website}`} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        <Globe className="w-4 h-4" />
                     </a>
                 )}
             </div>
         </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-neutral-200 dark:border-white/5">
          <button onClick={() => setActiveTab('overview')} className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 ${activeTab === 'overview' ? 'border-accent text-accent bg-accent/5' : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}>Overview</button>
          <button onClick={() => setActiveTab('insights')} className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 ${activeTab === 'insights' ? 'border-accent text-accent bg-accent/5' : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}>Insights</button>
          <button onClick={() => setActiveTab('outreach')} className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 ${activeTab === 'outreach' ? 'border-accent text-accent bg-accent/5' : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}>Outreach</button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-neutral-50/30 dark:bg-neutral-900/30">

        {/* TAB: OVERVIEW */}
        {activeTab === 'overview' && (
            <div className="space-y-6 animate-fade-in">
                <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                    <h3 className="text-xs font-bold text-neutral-500 uppercase mb-3">Company Overview</h3>
                    <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
                        {company.description}
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                        <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Award className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Hero Product</span>
                        </div>
                        <p className="text-sm font-medium text-neutral-900 dark:text-white">{company.heroProduct}</p>
                    </div>
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                         <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Target className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Identified Needs</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {company.needs.map((need, i) => (
                                <span key={i} className="px-2 py-1 rounded text-[10px] font-bold bg-neutral-100 dark:bg-white/10 text-neutral-600 dark:text-neutral-300">
                                    {need}
                                </span>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* TAB: INSIGHTS (EVIDENCE) */}
        {activeTab === 'insights' && (
             <div className="space-y-4 animate-fade-in">
                {company.signals.length === 0 ? (
                    <div className="text-center py-10 text-neutral-500">
                        <p className="text-sm">No specific insights detected.</p>
                    </div>
                ) : (
                    company.signals.map((signal, idx) => (
                        <div key={idx} className="flex gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 items-start">
                             <div className="mt-1 p-2 rounded-lg bg-neutral-50 dark:bg-white/5">
                                 {getSignalIcon(signal.type)}
                             </div>
                             <div>
                                 <div className="flex items-center gap-2 mb-1">
                                     <span className="text-xs font-bold uppercase text-neutral-900 dark:text-white">{signal.type}</span>
                                     <span className={`text-[9px] px-1.5 py-0.5 rounded ${signal.confidence === 'High' ? 'bg-green-500/10 text-green-500' : 'bg-neutral-500/10 text-neutral-500'}`}>
                                         {signal.confidence} Confidence
                                     </span>
                                 </div>
                                 <p className="text-sm text-neutral-600 dark:text-neutral-400 leading-snug">{signal.text}</p>
                             </div>
                        </div>
                    ))
                )}
                 <div className="p-4 rounded-xl bg-amber-50/50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-500/20 text-xs text-amber-800 dark:text-amber-500 leading-relaxed">
                    <strong className="block mb-1">AI Analysis:</strong>
                    {company.scoreReasoning || "Automated assessment based on visible digital footprint and relevance."}
                 </div>
             </div>
        )}

        {/* TAB: OUTREACH (COMMS) */}
        {activeTab === 'outreach' && (
            <div className="h-full flex flex-col animate-fade-in">
                <div className="mb-4">
                    <label className="text-xs font-bold text-neutral-500 uppercase mb-2 block">Your Offer / Skills</label>
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={skills}
                            onChange={(e) => setSkills(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleGenerate()}
                            placeholder="e.g. SEO services for e-commerce" 
                            className="flex-1 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-white/10 rounded-lg px-3 py-2 text-sm text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent"
                        />
                        <button 
                            onClick={handleGenerate}
                            disabled={!skills || isGenerating}
                            className={`px-4 rounded-lg bg-accent text-white hover:bg-accent-glow disabled:opacity-50 transition-colors shadow-sm`}
                        >
                            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                        </button>
                    </div>
                </div>

                {generatedPitches.length > 0 ? (
                    <div className="flex-1 flex flex-col bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-white/10 overflow-hidden">
                        <div className="flex border-b border-neutral-200 dark:border-white/5">
                            {generatedPitches.map((p, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => { setActivePitchIndex(idx); setIsEditing(false); }}
                                    className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider transition-colors ${idx === activePitchIndex ? 'text-accent bg-accent/5' : 'text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'}`}
                                >
                                    {p.angle}
                                </button>
                            ))}
                        </div>
                        <div className="flex-1 p-4 overflow-y-auto">
                             <div className="mb-3">
                                <span className="text-[10px] font-bold text-neutral-400 uppercase">Subject</span>
                                <p className="text-sm font-medium text-neutral-900 dark:text-white select-all">{currentPitch.subject}</p>
                             </div>
                             <div className="h-px bg-neutral-100 dark:bg-white/5 my-3"></div>
                             {isEditing ? (
                                <textarea 
                                    value={currentPitch.body}
                                    onChange={(e) => {
                                        const newPitches = [...generatedPitches];
                                        newPitches[activePitchIndex].body = e.target.value;
                                        setGeneratedPitches(newPitches);
                                    }}
                                    className="w-full h-40 bg-transparent resize-none focus:outline-none text-sm leading-relaxed p-0"
                                />
                             ) : (
                                <p className="text-sm text-neutral-600 dark:text-neutral-300 whitespace-pre-wrap leading-relaxed select-all">
                                    {currentPitch.body}
                                </p>
                             )}
                        </div>
                         <div className="p-2 border-t border-neutral-200 dark:border-white/5 bg-neutral-50 dark:bg-black/20 flex justify-between items-center">
                             <button onClick={() => setIsEditing(!isEditing)} className="p-2 hover:bg-neutral-200 dark:hover:bg-white/10 rounded text-neutral-500">
                                 <Edit3 className="w-4 h-4" />
                             </button>
                             <div className="flex gap-2">
                                <a href={`mailto:${company.email}?subject=${encodeURIComponent(currentPitch.subject)}&body=${encodeURIComponent(currentPitch.body)}`} className="p-2 rounded hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-600 dark:text-white">
                                    <Mail className="w-4 h-4" />
                                </a>
                                <button onClick={() => copyToClipboard(`Subject: ${currentPitch.subject}\n\n${currentPitch.body}`)} className="p-2 rounded bg-accent text-white shadow-sm hover:bg-accent-glow">
                                    {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                </button>
                             </div>
                        </div>
                    </div>
                ) : (
                     <div className="flex-1 flex flex-col items-center justify-center text-neutral-400 opacity-50 border-2 border-dashed border-neutral-200 dark:border-white/5 rounded-xl">
                        <Bot className="w-6 h-6 mb-2" />
                        <span className="text-xs">Enter skills to generate email drafts</span>
                     </div>
                )}
            </div>
        )}

      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    if (typeof process === 'undefined') {
      (globalThis as any).process = { env: {} };
    }

    const { request, env } = context;
    const apiKey = env.API_KEY || (typeof process !== 'undefined' ? process.env.API_KEY : null);

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "Server Configuration Error: API Key missing." }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
      });
    }

    const { mode, industry, city, companyName, excludeNames } = await request.json();

    if (mode === 'lookup') {
        if (!companyName) return new Response(JSON.stringify({ error: "Company Name is required for lookup" }), { status: 400 });
    } else {
        if (!industry || !city) return new Response(JSON.stringify({ error: "Industry and City are required" }), { status: 400 });
    }

    const ai = new GoogleGenAI({ apiKey: apiKey });

    // Using Gemini 3 Flash Preview for optimal speed and search grounding support
    const model = 'gemini-3-flash-preview';

    const exclusionList = excludeNames && excludeNames.length > 0 ? excludeNames.join(', ') : "None";

    let prompt = '';

    const jsonStructure = `
    {
      "leads": [
        {
          "name": "string",
          "website": "string (Full URL starting with https://)",
          "location": "string",
          "description": "string (Max 15 words)",
          "needs": ["string (Key needs only)"],
          "heroProduct": "string",
          "phone": "string (MUST TRY TO FIND - SEARCH HARD)",
          "email": "string (MUST TRY TO FIND - SEARCH HARD)",
          "socials": "string (Space separated FULL URLs starting with https:// - REQUIRED)",
          "hotScore": number (0-100),
          "signals": [
            { 
               "type": "string", 
               "text": "string (Concise evidence)",
               "confidence": "High" | "Medium" | "Low"
            }
          ]
        }
      ]
    }
    `;

    // SYSTEM INSTRUCTION: Sets the baseline behavior to be aggressive about contacts
    const systemInstruction = `
      You are an expert Lead Generation AI agent.

      CORE DIRECTIVE: You MUST prioritize finding CONTACT INFORMATION (Phone, Email, Social Links) above all else.

      SEARCH RULES:
      1. Always search for "[Company] contact phone email".
      2. Always search for "[Company] facebook instagram linkedin" to find social profiles, as they often contain phone numbers/emails missing from websites.
      3. If a direct email is missing, look for "info@", "hello@", or "contact@" addresses on their homepage or social media.
      4. Do not return "N/A" for Phone or Email unless you have verified it does not exist on their Website, Facebook, AND Instagram.
      5. Ensure all website and social URLs are FULL and VALID (start with https://).
    `;

    if (mode === 'lookup') {
        prompt = `
            DEEP OSINT TASK: Target "${companyName}" in "${city || 'any location'}".

            OBJECTIVE: Find confirmed contact details (Phone, Email, Socials).

            PROTOCOL:
            1. Search for official website.
            2. Search for "${companyName} contact email phone".
            3. Search for "${companyName} LinkedIn" or Facebook to find contact info in profiles.

            Return JSON only. Structure:
            ${jsonStructure}
        `;
    } else {
        prompt = `
            SCOUT MISSION: Find 5 ACTIVE ${industry} companies in ${city}.
            Exclude: ${exclusionList}.

            CRITICAL: For every lead found, you must perform a secondary search for their contact info.

            PROTOCOL:
            1. SEARCH: "${industry} companies ${city} directory".
            2. FOR EACH LEAD:
               - Search for "[Lead Name] ${city} phone email social media".
               - Check the snippets for phone numbers (look for local area codes).
               - Check the snippets for emails (look for @ symbol).

            Return JSON only. Structure:
            ${jsonStructure}
        `;
    }

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        tools: [
            { googleSearch: {} } 
        ],
        temperature: 0.4,
        systemInstruction: systemInstruction
      },
    });

    let text = response.text || "{}";

    // Robust JSON extraction
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        text = text.substring(firstBrace, lastBrace + 1);
    }

    let data;
    try {
        data = JSON.parse(text);
    } catch (e) {
        console.error("JSON Parse Error on text:", text);
        return new Response(JSON.stringify({ error: "Failed to parse AI response. Please try again." }), { 
            status: 500,
            headers: { "Content-Type": "application/json" }
        });
    }

    const leads = (data.leads || []).map((lead: any, index: number) => ({
        ...lead,
        id: `gen-${Date.now()}-${index}`,
        status: 'New',
        recentWork: lead.description, 
        website: lead.website || "N/A",
        phone: lead.phone || "N/A",
        email: lead.email || "N/A",
        socials: lead.socials || "N/A",
        signals: lead.signals || [],
        location: lead.location || city
    }));

    return new Response(JSON.stringify({ leads }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    console.error("Leads API Critical Error:", error);
    return new Response(JSON.stringify({ error: error.message || "Unknown Server Error" }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
    });
  }
};

import React, { useState } from 'react';
import { Target, Send, Loader2, Sparkles, Copy, Check, Bot, Phone, Mail, Award, Globe, Linkedin, Twitter, Facebook, Instagram, Youtube, Link as LinkIcon, Zap, TrendingUp, DollarSign, Newspaper, Edit3, Bookmark, ShieldCheck, MapPin, Briefcase } from 'lucide-react';
import { Company, Pitch } from '../types';
import { generatePitch } from '../services/geminiService';

interface IntelligencePaneProps {
  company: Company | null;
  onToggleSave: () => void;
  isSaved: boolean;
}

type Tab = 'overview' | 'insights' | 'outreach';

export const IntelligencePane: React.FC<IntelligencePaneProps> = ({ company, onToggleSave, isSaved }) => {
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [skills, setSkills] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedPitches, setGeneratedPitches] = useState<Pitch[]>([]);
  const [activePitchIndex, setActivePitchIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  React.useEffect(() => {
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
    setActiveTab('overview');
  }, [company?.id]);

  const handleGenerate = async () => {
    if (!company || !skills) return;

    setIsGenerating(true);
    setGeneratedPitches([]);
    try {
      // Pass the found signals to the pitcher for context
      const signalContext = company.signals.map(s => `${s.type}: ${s.text}`);

      const results = await generatePitch({
        companyName: company.name,
        industry: company.industry,
        userSkills: skills,
        tone: 'Professional',
        companySignals: signalContext
      });
      setGeneratedPitches(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getSignalIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('fund') || t.includes('money')) return <DollarSign className="w-3 h-3 text-emerald-500" />;
    if (t.includes('hir') || t.includes('team') || t.includes('growth')) return <TrendingUp className="w-3 h-3 text-blue-500" />;
    if (t.includes('news') || t.includes('press')) return <Newspaper className="w-3 h-3 text-purple-500" />;
    if (t.includes('loc') || t.includes('hq')) return <MapPin className="w-3 h-3 text-orange-500" />;
    return <ShieldCheck className="w-3 h-3 text-accent" />;
  };

  const getSocialLinks = () => {
    if (!company || !company.socials || company.socials === 'N/A' || company.socials === 'None') return [];

    // Split by spaces, commas, or newlines to handle various AI outputs
    return company.socials
      .split(/[\s,\n]+/)
      .map(s => s.trim())
      .filter(s => s.length > 0 && !s.toLowerCase().includes('n/a'))
      .map((rawLink, index) => {
        // Clean potential markdown or brackets formatting
        let url = rawLink.replace(/[\[\]()]/g, '');

        // Ensure protocol exists
        if (!url.startsWith('http')) {
            url = `https://${url}`;
        }

        // Basic validation: must include a dot and have minimal length to be a URL
        if (!url.includes('.') || url.length < 8) return null;

        let icon = <LinkIcon className="w-4 h-4" />;
        const lowerUrl = url.toLowerCase();

        if (lowerUrl.includes('linkedin')) icon = <Linkedin className="w-4 h-4" />;
        else if (lowerUrl.includes('twitter') || lowerUrl.includes('x.com')) icon = <Twitter className="w-4 h-4" />;
        else if (lowerUrl.includes('facebook')) icon = <Facebook className="w-4 h-4" />;
        else if (lowerUrl.includes('instagram')) icon = <Instagram className="w-4 h-4" />;
        else if (lowerUrl.includes('youtube')) icon = <Youtube className="w-4 h-4" />;

        return { url, icon, key: index };
      })
      .filter((link): link is { url: string; icon: React.ReactElement; key: number } => link !== null);
  };

  if (!company) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-neutral-400 select-none">
        <div className="w-20 h-20 rounded-3xl bg-neutral-100 dark:bg-neutral-900/50 flex items-center justify-center mb-6 ring-1 ring-neutral-200 dark:ring-white/5">
          <Target className="w-8 h-8 opacity-20" />
        </div>
        <h3 className="text-base font-semibold text-neutral-900 dark:text-white mb-2">Company Selection Required</h3>
        <p className="text-sm max-w-xs text-center leading-relaxed opacity-60">Select a lead from the list or your saved items to view company details.</p>
      </div>
    );
  }

  const socialLinks = getSocialLinks();
  const currentPitch = generatedPitches[activePitchIndex];

  return (
    <div className="h-full flex flex-col bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-white/10 shadow-glass overflow-hidden">

      {/* Header */}
      <div className="p-6 border-b border-neutral-200 dark:border-white/5 bg-neutral-50/50 dark:bg-black/20">
         <div className="flex justify-between items-start mb-4">
             <div>
                 <h2 className="text-xl font-bold text-neutral-900 dark:text-white tracking-tight">{company.name}</h2>
                 <div className="flex items-center gap-2 text-xs text-neutral-500 mt-1">
                     <Briefcase className="w-3 h-3" />
                     <span>{company.industry}</span>
                     <span className="text-neutral-300 dark:text-neutral-700">•</span>
                     <MapPin className="w-3 h-3" />
                     <span>{company.location || "Unknown Location"}</span>
                 </div>
             </div>

             <button 
                onClick={onToggleSave}
                className={`p-2 rounded-lg border transition-all ${isSaved ? 'bg-accent/10 border-accent text-accent' : 'bg-white dark:bg-neutral-800 border-neutral-200 dark:border-white/10 text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                title={isSaved ? "Remove from List" : "Save to List"}
             >
                 <Bookmark className={`w-4 h-4 ${isSaved ? 'fill-accent' : ''}`} />
             </button>
         </div>

         {/* Stats Bar */}
         <div className="flex items-center gap-4">
             <div className="px-3 py-1.5 rounded-md bg-neutral-100 dark:bg-white/5 border border-neutral-200 dark:border-white/5 flex items-center gap-2">
                 <Zap className="w-3 h-3 text-amber-500" />
                 <span className="text-xs font-bold text-neutral-700 dark:text-neutral-300">Match: {company.hotScore}%</span>
             </div>
             <div className="flex gap-2">
                 {socialLinks.map(link => (
                     <a key={link.key} href={link.url} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        {link.icon}
                     </a>
                 ))}
                 {company.website !== 'N/A' && (
                     <a href={company.website.startsWith('http') ? company.website : `https://${company.website}`} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        <Globe className="w-4 h-4" />
                     </a>
                 )}
             </div>
         </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-neutral-200 dark:border-white/5">
          <button onClick={() => setActiveTab('overview')} className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 ${activeTab === 'overview' ? 'border-accent text-accent bg-accent/5' : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}>Overview</button>
          <button onClick={() => setActiveTab('insights')} className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 ${activeTab === 'insights' ? 'border-accent text-accent bg-accent/5' : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}>Insights</button>
          <button onClick={() => setActiveTab('outreach')} className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 ${activeTab === 'outreach' ? 'border-accent text-accent bg-accent/5' : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}>Outreach</button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-neutral-50/30 dark:bg-neutral-900/30">

        {/* TAB: OVERVIEW */}
        {activeTab === 'overview' && (
            <div className="space-y-6 animate-fade-in">
                <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                    <h3 className="text-xs font-bold text-neutral-500 uppercase mb-3">Company Overview</h3>
                    <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
                        {company.description}
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                        <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Award className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Hero Product</span>
                        </div>
                        <p className="text-sm font-medium text-neutral-900 dark:text-white">{company.heroProduct}</p>
                    </div>
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                         <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Target className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Identified Needs</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {company.needs.map((need, i) => (
                                <span key={i} className="px-2 py-1 rounded text-[10px] font-bold bg-neutral-100 dark:bg-white/10 text-neutral-600 dark:text-neutral-300">
                                    {need}
                                </span>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* TAB: INSIGHTS (EVIDENCE) */}
        {activeTab === 'insights' && (
             <div className="space-y-4 animate-fade-in">
                {company.signals.length === 0 ? (
                    <div className="text-center py-10 text-neutral-500">
                        <p className="text-sm">No specific insights detected.</p>
                    </div>
                ) : (
                    company.signals.map((signal, idx) => (
                        <div key={idx} className="flex gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 items-start">
                             <div className="mt-1 p-2 rounded-lg bg-neutral-50 dark:bg-white/5">
                                 {getSignalIcon(signal.type)}
                             </div>
                             <div>
                                 <div className="flex items-center gap-2 mb-1">
                                     <span className="text-xs font-bold uppercase text-neutral-900 dark:text-white">{signal.type}</span>
                                     <span className={`text-[9px] px-1.5 py-0.5 rounded ${signal.confidence === 'High' ? 'bg-green-500/10 text-green-500' : 'bg-neutral-500/10 text-neutral-500'}`}>
                                         {signal.confidence} Confidence
                                     </span>
                                 </div>
                                 <p className="text-sm text-neutral-600 dark:text-neutral-400 leading-snug">{signal.text}</p>
                             </div>
                        </div>
                    ))
                )}
                 <div className="p-4 rounded-xl bg-amber-50/50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-500/20 text-xs text-amber-800 dark:text-amber-500 leading-relaxed">
                    <strong className="block mb-1">AI Analysis:</strong>
                    {company.scoreReasoning || "Automated assessment based on visible digital footprint and relevance."}
                 </div>
             </div>
        )}

        {/* TAB: OUTREACH (COMMS) */}
        {activeTab === 'outreach' && (
            <div className="h-full flex flex-col animate-fade-in">
                <div className="mb-4">
                    <label className="text-xs font-bold text-neutral-500 uppercase mb-2 block">Your Offer / Skills</label>
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={skills}
                            onChange={(e) => setSkills(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleGenerate()}
                            placeholder="e.g. SEO services for e-commerce" 
                            className="flex-1 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-white/10 rounded-lg px-3 py-2 text-sm text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent"
                        />
                        <button 
                            onClick={handleGenerate}
                            disabled={!skills || isGenerating}
                            className={`px-4 rounded-lg bg-accent text-white hover:bg-accent-glow disabled:opacity-50 transition-colors shadow-sm`}
                        >
                            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                        </button>
                    </div>
                </div>

                {generatedPitches.length > 0 ? (
                    <div className="flex-1 flex flex-col bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-white/10 overflow-hidden">
                        <div className="flex border-b border-neutral-200 dark:border-white/5">
                            {generatedPitches.map((p, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => { setActivePitchIndex(idx); setIsEditing(false); }}
                                    className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider transition-colors ${idx === activePitchIndex ? 'text-accent bg-accent/5' : 'text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'}`}
                                >
                                    {p.angle}
                                </button>
                            ))}
                        </div>
                        <div className="flex-1 p-4 overflow-y-auto">
                             <div className="mb-3">
                                <span className="text-[10px] font-bold text-neutral-400 uppercase">Subject</span>
                                <p className="text-sm font-medium text-neutral-900 dark:text-white select-all">{currentPitch.subject}</p>
                             </div>
                             <div className="h-px bg-neutral-100 dark:bg-white/5 my-3"></div>
                             {isEditing ? (
                                <textarea 
                                    value={currentPitch.body}
                                    onChange={(e) => {
                                        const newPitches = [...generatedPitches];
                                        newPitches[activePitchIndex].body = e.target.value;
                                        setGeneratedPitches(newPitches);
                                    }}
                                    className="w-full h-40 bg-transparent resize-none focus:outline-none text-sm leading-relaxed p-0"
                                />
                             ) : (
                                <p className="text-sm text-neutral-600 dark:text-neutral-300 whitespace-pre-wrap leading-relaxed select-all">
                                    {currentPitch.body}
                                </p>
                             )}
                        </div>
                         <div className="p-2 border-t border-neutral-200 dark:border-white/5 bg-neutral-50 dark:bg-black/20 flex justify-between items-center">
                             <button onClick={() => setIsEditing(!isEditing)} className="p-2 hover:bg-neutral-200 dark:hover:bg-white/10 rounded text-neutral-500">
                                 <Edit3 className="w-4 h-4" />
                             </button>
                             <div className="flex gap-2">
                                <a href={`mailto:${company.email}?subject=${encodeURIComponent(currentPitch.subject)}&body=${encodeURIComponent(currentPitch.body)}`} className="p-2 rounded hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-600 dark:text-white">
                                    <Mail className="w-4 h-4" />
                                </a>
                                <button onClick={() => copyToClipboard(`Subject: ${currentPitch.subject}\n\n${currentPitch.body}`)} className="p-2 rounded bg-accent text-white shadow-sm hover:bg-accent-glow">
                                    {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                </button>
                             </div>
                        </div>
                    </div>
                ) : (
                     <div className="flex-1 flex flex-col items-center justify-center text-neutral-400 opacity-50 border-2 border-dashed border-neutral-200 dark:border-white/5 rounded-xl">
                        <Bot className="w-6 h-6 mb-2" />
                        <span className="text-xs">Enter skills to generate email drafts</span>
                     </div>
                )}
            </div>
        )}

      </div>
    </div>
  );
};
